import sys
from collections import deque

def doctorStrange(N, M, graph):
    adj = [[] for _ in range(N+1)]
    for u, v in graph:
        adj[u].append(v)
        adj[v].append(u)

    count = 0
    visited = [False] * (N + 1)

    for i in range(1, N+1):
        if not visited[i]:
            queue = deque()
            queue.append(i)
            visited[i] = True
            size = 0
            while queue:
                u = queue.popleft()
                size += 1
                for v in adj[u]:
                    if not visited[v]:
                        visited[v] = True
                        queue.append(v)
            if size == N:
                continue
            count += 1

    return count
